'use strict';

var React = require('./index.js');

function jsx(type, props, key) {
  var merged = {};
  if (props !== undefined && props !== null) {
    for (var name in props) merged[name] = props[name];
  }
  return { type: type, props: merged, key: key };
}

exports.Fragment = 'fragment';
exports.jsx = jsx;
exports.jsxs = jsx;
